<script setup>
import emojiDefs from 'markdown-it-emoji/lib/data/full.json'
import markdown from 'markdown'
</script>

<template>
  <div class="flex flex-wrap gap-2">
    <div v-for="emoji in filteredEmojis" :key="emoji" class="cursor-pointer" @click="selectEmoji(emoji)">
      <markdown :content="emoji" />
    </div>
  </div>
</template>

<script>
export default {
  props: ['emojiName'],
  data() {
    return {
      maxEmojis: 5
    }
  },
  computed: {
    // Create a filtered list of emojis based on the emojiName prop
    filteredEmojis() {
      return Object.keys(emojiDefs)
        .filter(emoji => emoji.includes(this.emojiName))
        .slice(0, this.maxEmojis)
        .map(emoji => emojiDefs[emoji])
    }
  },
  methods: {
    // Emit the selected emoji to the parent component
    selectEmoji(emoji) {
      this.$emit('emoji', emoji)
    }
  }
}
</script>
